message.content:
{
  "description": "The creature is a quadrupedal mammal shown in right-facing profile with the overall size, proportions, shaggy fur, head shape, paws and claws of a brown bear, but with a single long curved horn on its forehead and a large glossy dark brown shell covering most of its dorsal side from behind the neck to above the hindquarters. The body is covered in dense long brown fur that is lighter cream-tan on the muzzle, chest and underside, standing on four thick legs with a short stubby tail at the rear, while the shell is domed, heavily ridged and divided into two main sections that sit on top of the fur.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like with an elongated snout, black nose with visible nostrils, small brown eyes, light tan fur on the muzzle and around the mouth, and dense brown fur on the cheeks and forehead",
      "where": "at the front end of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "single thick dark brown to black horn, smooth and glossy, broad at the base on the forehead between the eyes and tapering to a sharp point that curves backward then upward",
      "where": "centered on the forehead on top of the head between the ears and eyes"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in short brown fur, with slightly darker interiors",
      "where": "on top of the head behind the horn, one on each side"
    },
    {
      "part": "legs",
      "looks_like": "four thick sturdy legs covered in long shaggy dark brown fur, with heavier fur on the upper portions",
      "where": "two front legs under the chest/shoulder and two hind legs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with visible pale curved claws, three to five claws per paw protruding from the fur",
      "where": "at the bottom ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "very short stubby tuft of brown fur",
      "where": "at the extreme rear of the body on the left side, just below the rear edge of the shell"
    },
    {
      "part": "shell",
      "looks_like": "large glossy dark reddish-brown domed shell with fine transverse ridges and reflective highlights, divided into a smaller anterior dome over the shoulders and a larger posterior dome over the back, with a narrow joint between them",
      "where": "covering the entire dorsal back from just behind the neck to just above the tail, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "a border of small rectangular to oval segmented plates with a central circular depression on each, forming a scalloped edge, lighter brown than the main shell",
      "where": "running along the lower lateral margin of both shell sections"
    },
    {
      "part": "markings",
      "looks_like": "lighter cream to pale tan fur contrasting with the darker brown, with no spots or stripes",
      "where": "on the muzzle, lower cheeks, chest, and along the underside/belly between the front and hind legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
